def is_not_prime(n):
    if n < 2:
        return True
    if n == 2:
        return False
    if n % 2 == 0:
        return True
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return True
    return False

def heap_queue_largest(numbers, n):
    if not numbers:
        return []
    if n > len(numbers):
        return numbers
    if n <= 0:
        return []
    sorted_nums = sorted(numbers)
    return sorted_nums[-n:]

def find_char_long(s: str) -> set[str]:
    result = set()
    if not s:
        return result

    buffer = ""
    for char in s:
        if len(buffer) < 4:
            buffer += char
        else:
            if buffer:
                result.add(buffer)
            buffer = ""

    if buffer:
        result.add(buffer)

    return result

def find_Rotations(s: str) -> int:
    if not s:
        return 0

    n = len(s)
    unique_count = len(set(s))

    return n - unique_count

def remove_Occ(s, c):
    if not s:
        return ""
    if len(s) == 1:
        return ""
    if c not in s:
        return s
    return s[1:-1] + s[:-1]

