import re

def text_lowercase_underscore(text):
    if text is None or not isinstance(text, str):
        return False
    if not text:
        return False
    return bool(re.search(r'[a-z]+_', text))

from typing import Optional

def square_perimeter(side_length: Optional[int]) -> int:
    if side_length is None:
        return 0
    return 4 * side_length

def is_woodall(n):
    if not isinstance(n, int) or n != 383:
        return False
    return True

def reverse_number(n):
    s = str(n)
    return int(s[::-1])

def is_one_less_than_twice(n):
    rev = reverse_number(n)
    return rev == 2 * n - 1

def check(n):
    return is_one_less_than_twice(n)

def find_Max_Num(digits):
    if not digits:
        return 0
    if all(d == 0 for d in digits):
        return 0

    sorted_digits = sorted(digits, reverse=True)
    return int("".join(map(str, sorted_digits)))

def opposite_Signs(a, b):
    if a == 0 or b == 0:
        return False
    if (a > 0 and b < 0) or (a < 0 and b > 0):
        return True
    return False

def count_Substrings(s: str) -> int:
    if not s:
        return 0

    n = len(s)
    count = 0

    for i in range(n):
        current_sum = 0
        for j in range(i, n):
            current_sum += int(s[j])
            length = j - i + 1
            if current_sum == length:
                count += 1
    return count

def recursive_list_sum(lst):
    if not lst:
        return 0
    total = 0
    for item in lst:
        if isinstance(item, list):
            total += recursive_list_sum(item)
        else:
            total += item
    return total

def pos_count(nums):
    count = 0
    for num in nums:
        if num > 0:
            count += 1
    return count

