    if not arr:
        return arr

    n = len(arr)
    gap = n // 2
    sorted_flag = True

    while sorted_flag and gap > 0:
        sorted_flag = False
        for i in range(0, n, gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                sorted_flag = True
        gap = gap // 2

    return arr

