def is_undulating(n):
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")

    s = str(n)
    length = len(s)

    # Single digit numbers are technically undulating (alternating between itself)
    if length == 1:
        return True

    # Must have even length
    if length % 2 != 0:
        return False

    # First and last digits must be different
    if s[0] == s[-1]:
        return False

    # Check strict alternation
    for i in range(1, length - 1):
        if s[i] == s[i-1] or s[i] == s[i+1]:
            return False

    return True

