import math

def multiply_num(numbers):
    if not numbers:
        return 0.0

    product = 1.0
    for num in numbers:
        product *= num

    return product / len(numbers)

def next_smallest_palindrome(n):
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")
    if n < 0:
        raise ValueError("Input must be a non-negative integer")

    if n == 0:
        return 1

    start = n + 1
    while True:
        palindrome = construct_palindrome(start)
        if palindrome >= n:
            return palindrome
        start += 1

def construct_palindrome(num):
    s = str(num)
    length = len(s)
    if length % 2 == 0:
        half = s[:length // 2]
        return half + half[::-1]
    else:
        half = s[:length // 2]
        return half + s[length // 2] + half[::-1]

def kth_element(arr, k):
