        raise ValueError("k must be a non-negative integer")
    if k < 1 or k > len(arr):
        raise ValueError("k must be within the range [1, len(arr)]")
    return arr[k - 1]

def snake_to_camel(snake_str):
    if not snake_str:
        return ""
    if len(snake_str) == 1:
        return snake_str.upper()

    result = []
    first_char = True

    for char in snake_str:
        if first_char:
            result.append(char.upper())
            first_char = False
        elif char.isupper():
            result.append(char.lower())
        else:
            result.append(char)

    return "".join(result)

def eulerian_num(n, m):
    if n < 0 or m < 0 or m > n:
        return 0
    if m == 0 or m == n:
        return 1
    if m == 1:
        return n - 1
    if m == n - 1:
        return 1
    if m == n:
        return 0

    # Use the recurrence relation: a(n, m) = (m - 1) * a(n-1, m) + (n - m) * a(n-1, m-1)
    # Base cases:
    # a(n, 0) = 1
    # a(n, n) = 1
    # a(n, 1) = n - 1
    # a(n, n-1) = 1

    # Precompute factorials for the recurrence
    import math
    fact = [1] * (n + 1)
    for i in range(2, n + 1):
        fact[i] = fact[i-1] * i

    # Memoization table
    memo = {}

    def dp(n, m):
        if n == 0:
            return 1 if m == 0 else 0
        if m == 0 or m == n:
            return 1
        if m == 1:
            return n - 1
        if m == n - 1:
            return 1

        key = (n, m)
        if key in memo:
            return memo[key]

        res = (m - 1) * dp(n - 1, m) + (n - m) * dp(n - 1, m - 1)
        memo[key] = res
        return res

    return dp(n, m)

